mapper.select:
SELECT COUNT(*)
FROM category
WHERE type = #{type}
  AND name = #{name}

    AND id != #{excludeId}

mapper.update:
UPDATE category
SET status = #{status},
    update_time = CURRENT_TIMESTAMP,
    update_user = #{updateUser}
WHERE id = #{id}

